import { createInMemoryQueue, createQueueName } from "@zudojs/queue";
import type { QueueContextCarrier } from "@zudojs/queue";

let current: string | undefined;
const carrier: QueueContextCarrier<string> = {
  key: "correlationId",
  capture: () => current,
  restore: async (value, run) => {
    const previous = current;
    current = value;
    try {
      return await run();
    } finally {
      current = previous;
    }
  },
};

const queue = createInMemoryQueue<{ invoiceId: number }>(createQueueName("deliveries"), { contextCarriers: [carrier] });
let done = 0;
queue.process("deliver", async (job) => {
  console.log(`invoice ${job.data.invoiceId} corr=${current}`);
  done += 1;
});

current = "req-41";
