const rows = [{ id: 1, status: "queued", claims: 0, lockedUntil: 0 }];

function claimDue(rows, now, leaseMs, maxClaims) {
  for (const row of rows) {
    if (row.status === "running" && row.lockedUntil < now && row.claims >= maxClaims) row.status = "dead";
  }
  const due = rows.filter((row) => row.status === "queued" || (row.status === "running" && row.lockedUntil < now));
  for (const row of due) {
    row.status = "running";
    row.claims += 1;
    row.lockedUntil = now + leaseMs;
  }
  return due.map((row) => row.id);
}

