];
const now = new Date("2026-10-05T09:05:00Z");

function oldestWaitingSeconds(deliveries, now) {
  const waiting = deliveries.filter((d) => d.status === "queued" || d.status === "running");
  if (waiting.length === 0) return 0;
  const oldest = Math.min(...waiting.map((d) => d.createdAt.getTime()));
  return Math.floor((now.getTime() - oldest) / 1000);
}

