    dead.push(job.data.id);
    return;
  }
});

await queue.add("deliver", { id: 1, email: "accounts@mamaput.ng" }, { attempts: 3 });
await queue.add("deliver", { id: 3, email: "not-an-email" }, { attempts: 3 });
while ((await queue.getStats()).succeeded < 2) await new Promise((resolve) => setTimeout(resolve, 10));
console.log("runs:", runs, "dead:", dead, "deadLettered:", (await queue.getStats()).deadLettered);
